from 写入第二遍 import add
add('08_003',7,'16:9，董白斜侧脸近景居画面中央，双马尾从左右后层垂入，眼睛与大笑嘴同框；镜头随她前探的小动作轻推，落在圆眼、内扬眉尖和吐气形。','董白张开的双臂从画外落下，头先向青探来，圆睁的眼中瞳孔缩成小点，眉尖带着兴奋向内上扬。她笑着说这是将功补过的机会，呼出一团短促白气形；说到状态绝佳，笑口更开，肩膀努力端平，鬓边细汗却滑了一小段，发尾还在慢慢摆。','头发两侧窄隙露出蓝灰天空与淡灰云层，低处薄尘在头后退成软边。','上方冷白漫射均匀，瞳孔和黑发对比清晰，汗珠用微小冷白点。','张臂后衣料回落细响，一口兴奋的呼气，远风。',ja=['この前トロールに負けた分を挽回する、いい機会だわ。','前とは違う。今の私は絶好調よ！'],tone='第一句兴奋地自我鼓劲，第二句抬高音量宣告；笑意用力但自认笃定。',kind='mixed',phase='state',meaning='原格兴奋圆眼、小瞳孔、上扬内眉、大笑与吐气保留，表现夸口的用力感。',characters=['董白'],card={'opening':'董白急于把上次失败翻过去。','beats':['探头兴奋解释，圆眼小瞳孔','吐气后更用力笑，端平肩膀宣告状态'],'coupling':'自信台词与努力支起的笑容、细汗并存。','landing':'自己信心很足，青却还需要判断。'})
add('09_001',7,'16:9，青侧脸特写居画面左侧，右侧留出她观察董白的视线空隙；固定机位，嘴角、圆眼与耳尖同框。','青静静望着董白，唇线先轻轻翘起一边，像被那股夸张气势带动；内心问能否交给她时，眼珠移向董白站稳的画外脚位，再回到脸的高度。想到还不知道实力，笑意收回一点，她嘴唇抿住，眉间轻蹙，身体仍保留愿意靠近协商的朝向。','蓝灰天空在右侧开阔，淡灰云层柔软重叠，发隙之外无建筑近物。','上方冷白柔光保持，耳缘与鼻梁亮面柔和。','风声穿过两人间，青的呼吸渐稳，发梢轻擦。',ja=['…任せても大丈夫かな？','魔族斬鉄団の人とはいっても、まだ実力が分からない。'],tone='内心由试着相信转为谨慎核对，语气关切而实际。',kind='mixed',phase='state',meaning='青侧脸观察董白，内心权衡能否托付。',characters=['青'],card={'opening':'青希望找到能接管的人，却缺少实力信息。','beats':['嘴角暂松，试着接住自信','视线扫向立足点再回脸，笑意收回'],'coupling':'内心判断落在真实观察与小幅表情变化上。','landing':'决定开口提出合作。'})
add('09_002',7,'16:9，董白半张脸占画面左侧近层，青在右后中景，青的手、头与腰侧姿态可见；固定机位，焦点先在青，董白反问时移向左侧眼睛。','青闭了下眼，抬手贴住额侧，肩膀随着一口气松下来；她把联手建议说得直接，空下的一手落在腰边，身体微向董白前倾。董白原本朝武士的眼珠猛移向青，笑口停住，圆眼睁得更大，短短反问；青的手还停在头侧，等她真正听进建议。','两人之间留蓝灰天空与分层浅灰云，低处米灰薄尘沿平台边缘漂移。','云天冷白漫射，近处董白黑发留窄亮边，远处青银发与衣色清楚。','青手掌拂到发侧的轻声，董白转头时马尾一晃，风声。',ja=['…一人であいつに勝てる？私も一緒に戦った方がいいと思うよ。','あ？'],tone='青疲惫地直问，后半句诚恳提议；董白短促反问，带被冒犯的意外。',kind='mixed',phase='state',meaning='董白近处半脸与青远处摸头提议的双层构图保留，反问接住建议。',characters=['青','董白'],card={'opening':'青把担心转换为可执行的联手方案。','beats':['闭眼扶头、放松肩膀开口','身体稍倾诚恳提议','董白骤移眼珠，笑停，反问'],'coupling':'青的让步语气与董白骤起的自尊冲突在同框发生。','landing':'建议没有获得接受，董白转向青。'})
